import{_ as a,o as r,c as t,a3 as o}from"./chunks/framework.D51OnBWA.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/preview/feat-labels/guide/faq.html"}],["meta",{"property":"og:title","content":"FAQ | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/preview/feat-labels/guide/faq.html"}],["meta",{"name":"twitter:title","content":"FAQ | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),n={name:"guide/faq.md"};function i(s,e,d,l,h,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="which-browsers-are-supported" tabindex="-1">Which browsers are supported? <a class="header-anchor" href="#which-browsers-are-supported" aria-label="Permalink to &quot;Which browsers are supported?&quot;">​</a></h2><p>Any with WebGPU and hardware acceleration enabled. As of late 2026 (<a href="https://github.com/gpuweb/gpuweb/wiki/implementation-status" target="_blank" rel="noreferrer">current status</a>):</p><ul><li><strong>Chrome / Edge</strong> 113+ on Windows, macOS and ChromeOS; 121+ on Android. On Linux, 144+ for Intel Gen12+ GPUs and 147+ for NVIDIA on Wayland; other setups need <code>--enable-unsafe-webgpu</code>.</li><li><strong>Safari</strong> 26+ on macOS, iOS, iPadOS and visionOS.</li><li><strong>Firefox</strong> 141+ on Windows; on Apple-silicon Macs 145+ (macOS 26) or 147+. Linux and Intel Macs: Nightly only.</li></ul><p>Without WebGPU, <code>KilnViewer.create()</code> rejects with an error, which the demo shows on the page.</p><h2 id="can-kiln-read-my-data" tabindex="-1">Can Kiln read my data? <a class="header-anchor" href="#can-kiln-read-my-data" aria-label="Permalink to &quot;Can Kiln read my data?&quot;">​</a></h2><ul><li><strong>OME-Zarr</strong> (NGFF v0.4/v0.5) loads directly from a URL or local directory: <code>uint8</code>, <code>uint16</code>, <code>int16</code>, <code>float32</code> (<code>float64</code> is read as <code>float32</code>). See <a href="/preview/feat-labels/data/ome-zarr.html">OME-Zarr</a>.</li><li><strong>Raw volumes</strong> are converted once to the <a href="/preview/feat-labels/data/sharded-binary.html">sharded binary format</a> with the bundled CLI.</li></ul><h2 id="why-won-t-my-dataset-load-from-s3-or-my-own-server" tabindex="-1">Why won&#39;t my dataset load from S3 or my own server? <a class="header-anchor" href="#why-won-t-my-dataset-load-from-s3-or-my-own-server" aria-label="Permalink to &quot;Why won&#39;t my dataset load from S3 or my own server?&quot;">​</a></h2><p>Almost always CORS. The server must send <code>Access-Control-Allow-Origin</code> for your site, and allow the <code>Range</code> header for sharded binary and sharded Zarr. See <a href="/preview/feat-labels/data/hosting.html">Hosting</a>.</p><h2 id="how-much-vram-does-kiln-use" tabindex="-1">How much VRAM does Kiln use? <a class="header-anchor" href="#how-much-vram-does-kiln-use" aria-label="Permalink to &quot;How much VRAM does Kiln use?&quot;">​</a></h2><p>The atlas and indirection table stay within a fixed budget, ~1.3 GiB by default (<code>atlasBudgetBytes</code>), whatever the dataset size. Render targets come on top. See <a href="/preview/feat-labels/architecture/memory-budget.html">Memory budget</a>.</p><h2 id="what-are-the-known-rendering-issues" tabindex="-1">What are the known rendering issues? <a class="header-anchor" href="#what-are-the-known-rendering-issues" aria-label="Permalink to &quot;What are the known rendering issues?&quot;">​</a></h2><p>See <a href="/preview/feat-labels/reference/issues.html">Known issues</a>.</p><h2 id="can-i-use-kiln-in-my-own-application" tabindex="-1">Can I use Kiln in my own application? <a class="header-anchor" href="#can-i-use-kiln-in-my-own-application" aria-label="Permalink to &quot;Can I use Kiln in my own application?&quot;">​</a></h2><p>Yes, it&#39;s on npm under Apache 2.0. Use <code>KilnViewer</code> (<a href="/preview/feat-labels/guide/quick-start.html">Quick start</a>), or <code>KilnEngine</code> if your app already has a WebGPU device and render loop (<a href="/preview/feat-labels/guide/quick-start.html#bring-your-own-device-and-frame-loop">Bring your own device</a>).</p>',15)])])}const p=a(n,[["render",i]]);export{m as __pageData,p as default};
